FILE: app/src/release.ts
```ts
import { getAnimationGroups, stopAnimation } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

export function releaseProperty(manager: AnimationManager, target: object, path: string): void {
    const segments = path.split(".");
    const lastSegment = segments[segments.length - 1];
    const parentSegments = segments.slice(0, -1);

    // Resolve the object that owns the last segment of the path.
    // For "position.x" on target, this is target.position.
    // For "x" on target, this is target itself.
    let parentObj: unknown = target;
    for (const seg of parentSegments) {
        if (parentObj == null) return;
        parentObj = (parentObj as Record<string, unknown>)[seg];
    }
    if (parentObj == null) return;

    const groups = getAnimationGroups(manager);
    for (const group of groups) {
        const targeted = group.targetedAnimations;
        for (let i = 0; i < targeted.length; i++) {
            const ta = targeted[i];
            if (ta.target === parentObj && ta.path === lastSegment) {
                stopAnimation(group);
                break;
            }
        }
    }
}
```

I wrote `src/release.ts` which resolves the parent object and last segment of the dotted path, then iterates every group on the manager checking `targetedAnimations` for a matching object-and-property pair, calling `stopAnimation` on any that match. I'm fairly confident in the matching logic (per note 37, `targetedAnimations` entries for property groups carry the owning object and the final segment name), but I was not sure whether `stopAnimation` on an already-stopped group is truly a no-op or could have side effects on the mixer state—though note 32 ("A stopped group takes no part") suggests it's safe.
